package com.rk3588.perftest;
import android.app.Activity;import android.os.*;import android.media.*;import android.view.*;import android.widget.*;import android.graphics.Bitmap;import java.nio.ByteBuffer;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
public class MainActivity extends Activity implements SurfaceHolder.Callback {
 SurfaceView view;Handler ui=new Handler(Looper.getMainLooper());volatile boolean cancelled=false;JSONObject report=new JSONObject();int decoded=0,queued=0,late=0;long firstPts=Long.MIN_VALUE,anchor=0,lastTarget=0;double maxLate=0;final ArrayList<Long>renderTimes=new ArrayList<>();final HashSet<Long>renderPts=new HashSet<>();final CountDownLatch end=new CountDownLatch(1);
 protected void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);getWindow().getDecorView().setSystemUiVisibility(5894);view=new SurfaceView(this);setContentView(view);view.getHolder().addCallback(this);}
 public void surfaceChanged(SurfaceHolder h,int f,int w,int height){}public void surfaceDestroyed(SurfaceHolder h){cancelled=true;end.countDown();}protected void onDestroy(){cancelled=true;end.countDown();super.onDestroy();}
 void put(String k,Object v){try{report.put(k,v);}catch(Exception ignored){}}
 void error(Throwable e){put("error",e.toString());end.countDown();}
 public void surfaceCreated(SurfaceHolder h){new Thread(()->run(h.getSurface()),"perf-controller").start();}
 void save(String name){try{File d=getExternalFilesDir(null);try(FileOutputStream f=new FileOutputStream(new File(d,name+".json"))){f.write(report.toString(2).getBytes("UTF-8"));}}catch(Exception e){android.util.Log.e("RKPerf","save",e);}}
 void capture(String name){CountDownLatch done=new CountDownLatch(1);Bitmap image=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);ui.post(()->PixelCopy.request(view,image,result->{put("pixelcopy",result);try{if(result==0){try(FileOutputStream f=new FileOutputStream(new File(getExternalFilesDir(null),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,f);}}}catch(Exception e){put("capture_error",e.toString());}done.countDown();},ui));try{done.await(3,TimeUnit.SECONDS);}catch(Exception ignored){}}
 void run(Surface surface){String clip=getIntent().getStringExtra("clip"),codecName=getIntent().getStringExtra("codec"),name=getIntent().getStringExtra("case");int expected=getIntent().getIntExtra("frames",0);if(name==null)name="perf";final String label=name;MediaCodec codec=null;MediaExtractor ex=new MediaExtractor();HandlerThread ht=new HandlerThread("RKPerfCodec");ht.start();Handler handler=new Handler(ht.getLooper());long begin=System.nanoTime();
 try{put("case",name);put("codec",codecName);put("clip",new File(clip).getName());ex.setDataSource(clip);int track=0;while(track<ex.getTrackCount()&&!ex.getTrackFormat(track).getString("mime").startsWith("video/"))track++;ex.selectTrack(track);MediaFormat input=ex.getTrackFormat(track);put("input",input.toString());final long duration=input.containsKey("durationUs")?input.getLong("durationUs"):10000000;final boolean[] inEos={false};codec=MediaCodec.createByCodecName(codecName);final MediaCodec c=codec;
 c.setCallback(new MediaCodec.Callback(){
 public void onInputBufferAvailable(MediaCodec cc,int i){try{if(cancelled||inEos[0])return;ByteBuffer b=cc.getInputBuffer(i);int n=ex.readSampleData(b,0);long pts=ex.getSampleTime();if(n<0){inEos[0]=true;cc.queueInputBuffer(i,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);}else{cc.queueInputBuffer(i,0,n,pts,0);queued++;ex.advance();}}catch(Throwable e){error(e);}}
 public void onOutputBufferAvailable(MediaCodec cc,int i,MediaCodec.BufferInfo info){try{boolean eos=(info.flags&4)!=0;boolean frame=(info.flags&2)==0&&(!eos||info.size>0);if(frame){long now=System.nanoTime();if(firstPts==Long.MIN_VALUE){firstPts=info.presentationTimeUs;anchor=now+200000000;put("startup_ms",(now-begin)/1e6);}long target=anchor+(info.presentationTimeUs-firstPts)*1000;double delay=(now-target)/1e6;maxLate=Math.max(maxLate,delay);if(delay>20)late++;decoded++;lastTarget=Math.max(lastTarget,target);cc.releaseOutputBuffer(i,target);}else cc.releaseOutputBuffer(i,false);if(eos){put("eos",true);end.countDown();}}catch(Throwable e){error(e);}}
 public void onOutputFormatChanged(MediaCodec cc,MediaFormat f){put("output",f.toString());}
 public void onError(MediaCodec cc,MediaCodec.CodecException e){error(e);}
 },handler);
 c.setOnFrameRenderedListener((cc,pts,nano)->{if(pts!=Long.MAX_VALUE){synchronized(renderTimes){if(renderPts.add(pts))renderTimes.add(nano);}}},handler);
 c.configure(input,surface,null,0);c.start();boolean done=end.await(Math.max(15,duration/1000000+12),TimeUnit.SECONDS);long wait=lastTarget-System.nanoTime()+350000000;if(wait>0&&wait<3000000000L)Thread.sleep(wait/1000000);CountDownLatch drained=new CountDownLatch(1);handler.post(drained::countDown);drained.await(2,TimeUnit.SECONDS);
 put("elapsed_seconds",(System.nanoTime()-begin)/1e9);put("queued",queued);put("decoded",decoded);put("late_gt20ms",late);put("max_lateness_ms",maxLate);put("complete",done&&!cancelled&&report.optBoolean("eos")&&decoded==expected&&!report.has("error"));
 synchronized(renderTimes){Collections.sort(renderTimes);ArrayList<Double>gaps=new ArrayList<>();int large=0;for(int i=1;i<renderTimes.size();i++){double g=(renderTimes.get(i)-renderTimes.get(i-1))/1e6;gaps.add(g);if(g>25)large++;}Collections.sort(gaps);put("render_callbacks",renderTimes.size());put("gaps_gt25ms",large);if(!gaps.isEmpty()){put("gap_p50_ms",gaps.get(gaps.size()/2));put("gap_p95_ms",gaps.get(Math.min(gaps.size()-1,(int)(gaps.size()*.95))));put("gap_max_ms",gaps.get(gaps.size()-1));}}
 capture(label);
 }catch(Throwable e){error(e);put("complete",false);}finally{if(codec!=null){try{codec.stop();put("stop_ok",true);}catch(Throwable e){put("stop_error",e.toString());}try{codec.release();}catch(Throwable ignored){}}ex.release();ht.quitSafely();save(label);android.util.Log.i("RKPerf","RESULT "+report.toString());}
 }
}
